def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    chain_dict = sorted(chain_dict.items(), key=lambda x: (-len(x[1]), x[0]))

    result = []
    current_token = chain_dict[0][0]

    for token in chain_dict:
        if token not in result:
            result.append(token)
            current_token = token

    return result

